// SandboxServiceHandler is an implementation of the agentruntime.sandbox.v1.SandboxService service.
type SandboxServiceHandler interface {
	// --- 工作区的只读操作（WS-READ-01）：不进 Temporal、不改环境的 busy、不触发存档 ---
	// 会话里有活着的可写环境时在它里面读（看得到没提交的改动）；挂卷时 ListFiles、ReadFile、Grep 直接读卷；存档模式读最近的
	// 快照（清单与块），不建环境。GetDiff、GetLog 在沙箱里跑 git（不在服务进程里对用户的仓库跑 git）。
	ListFiles(context.Context, *connect.Request[v1.ListFilesRequest]) (*connect.Response[v1.ListFilesResponse], error)
	ReadFile(context.Context, *connect.Request[v1.ReadFileRequest]) (*connect.Response[v1.ReadFileResponse], error)
	Grep(context.Context, *connect.Request[v1.GrepRequest]) (*connect.Response[v1.GrepResponse], error)
	GetDiff(context.Context, *connect.Request[v1.GetDiffRequest]) (*connect.Response[v1.GetDiffResponse], error)
	GetLog(context.Context, *connect.Request[v1.GetLogRequest]) (*connect.Response[v1.GetLogResponse], error)
	// 租户的沙箱策略摘要（首选后端、是否存档模式、工作区上限）；Worker 判断工作区怎么用时读它。
	DescribeTenant(context.Context, *connect.Request[v1.DescribeTenantRequest]) (*connect.Response[v1.DescribeTenantResponse], error)
	// --- 借还与执行 ---
	Acquire(context.Context, *connect.Request[v1.AcquireRequest]) (*connect.Response[v1.AcquireResponse], error)
	// 在借到的环境里执行一条命令。平台的环境变量（包镜像、出网代理、测试用密钥、.env）由服务按环境表补上，不出服务。
	Exec(context.Context, *connect.Request[v1.ExecRequest]) (*connect.Response[v1.ExecResponse], error)
	// Single-object uploads: the service chooses the key and signs only immutable prepared bytes.
	PrepareTransfer(context.Context, *connect.Request[v1.PrepareTransferRequest]) (*connect.Response[v1.PrepareTransferResponse], error)
	CommitTransfer(context.Context, *connect.Request[v1.CommitTransferRequest]) (*connect.Response[v1.CommitTransferResponse], error)
	WriteFile(context.Context, *connect.Request[v1.WriteFileRequest]) (*connect.Response[v1.WriteFileResponse], error)
	ReadLeaseFile(context.Context, *connect.Request[v1.ReadLeaseFileRequest]) (*connect.Response[v1.ReadLeaseFileResponse], error)
	ListLeaseDir(context.Context, *connect.Request[v1.ListLeaseDirRequest]) (*connect.Response[v1.ListLeaseDirResponse], error)
	GrepLease(context.Context, *connect.Request[v1.GrepLeaseRequest]) (*connect.Response[v1.GrepLeaseResponse], error)
	// 工作目录的逐项清单（FileEntry 同 agentruntime_core.providers.sandbox，按路径排序）。
	Manifest(context.Context, *connect.Request[v1.ManifestRequest]) (*connect.Response[v1.ManifestResponse], error)
	// 工作目录打成 tar（语义同 SandboxArchive.export_archive），分块流回。
	ExportArchive(context.Context, *connect.Request[v1.ExportArchiveRequest], *connect.ServerStream[v1.ExportArchiveResponse]) error
	// 把 tar 解到空的工作目录：第一条消息带 header，之后每条带 chunk。
	ImportArchive(context.Context, *connect.ClientStream[v1.ImportArchiveRequest]) (*connect.Response[v1.ImportArchiveResponse], error)
	PreviewAddress(context.Context, *connect.Request[v1.PreviewAddressRequest]) (*connect.Response[v1.PreviewAddressResponse], error)
	// 用完：keep 时留着（会话级），否则销毁（存档模式的可写环境先存档）。
	Release(context.Context, *connect.Request[v1.ReleaseRequest]) (*connect.Response[v1.ReleaseResponse], error)
	// 把借到的环境里的工作区存一份快照。
	Snapshot(context.Context, *connect.Request[v1.SnapshotRequest]) (*connect.Response[v1.SnapshotResponse], error)
	// 后端里已经没有这个环境：记为丢失。
	Discard(context.Context, *connect.Request[v1.DiscardRequest]) (*connect.Response[v1.DiscardResponse], error)
	// --- 批量 ---
	DestroySession(context.Context, *connect.Request[v1.DestroySessionRequest]) (*connect.Response[v1.DestroySessionResponse], error)
	// 删除工作区时销毁它的全部环境（不存档，正在跑命令的也销毁），挂卷时一并删掉卷上的目录。
	DestroyWorkspace(context.Context, *connect.Request[v1.DestroyWorkspaceRequest]) (*connect.Response[v1.DestroyWorkspaceResponse], error)
	DestroyTenant(context.Context, *connect.Request[v1.DestroyTenantRequest]) (*connect.Response[v1.DestroyTenantResponse], error)
}

